mapper.select:
SELECT f.category AS category, (p.paid_at AT TIME ZONE 'Asia/Shanghai')::date AS day, coalesce(sum(a.amount), 0) AS amount FROM payment_allocation a JOIN payment p ON p.id = a.payment_id AND p.status = '正常' AND p.paid_at >= #{fromTs} AND p.paid_at < #{toTs} JOIN fee_item f ON f.id = a.item_id WHERE f.direction <> 'deposit'
AND p.community_id = #{communityId}
GROUP BY 1, 2 ORDER BY 1, 2

SELECT d.type_id AS type, t.direction AS direction, (t.occurred_at AT TIME ZONE 'Asia/Shanghai')::date AS day, coalesce(sum(t.amount), 0) AS amount FROM deposit_txn t JOIN deposit d ON d.id = t.deposit_id WHERE t.direction IN ('I', 'O') AND t.occurred_at >= #{fromTs} AND t.occurred_at < #{toTs}
AND d.community_id = #{communityId}
GROUP BY 1, 2, 3 ORDER BY 1, 2, 3

SELECT day, slot, source, sum(amount) AS amount FROM ( SELECT (p.paid_at AT TIME ZONE 'Asia/Shanghai')::date AS day, CASE WHEN p.method = '预存抵扣' THEN '预存抵扣' WHEN p.method = '现金' AND p.pay_point = '停车场' THEN '车辆现金' WHEN p.method = '现金' THEN '现金' WHEN p.method = 'POS' AND p.pay_point = '停车场' THEN '车辆POS' WHEN p.method = 'POS' THEN 'POS刷卡' WHEN p.method IN ('银行代扣', '转账', '银行转账') THEN '转账' WHEN p.method IN ('微信', '支付宝') AND p.pay_point = '停车场' THEN '车辆云平台' ELSE '线上支付' END AS slot, 'payment' AS source, p.amount AS amount FROM payment p WHERE p.status = '正常' AND p.paid_at >= #{fromTs} AND p.paid_at < #{toTs}
AND p.community_id = #{communityId}
UNION ALL SELECT (t.occurred_at AT TIME ZONE 'Asia/Shanghai')::date AS day, CASE WHEN t.method = '现金' THEN '现金' ELSE '转账' END AS slot, 'deposit' AS source, CASE t.direction WHEN 'I' THEN t.amount ELSE -t.amount END AS amount FROM deposit_txn t JOIN deposit d ON d.id = t.deposit_id WHERE t.direction IN ('I', 'O') AND t.occurred_at >= #{fromTs} AND t.occurred_at < #{toTs}
AND d.community_id = #{communityId}
) x GROUP BY day, slot, source ORDER BY day, slot
